package com.edgecloud.alert.service;
import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.*; import com.edgecloud.alert.dto.*; import com.edgecloud.alert.entity.*; import com.edgecloud.alert.exception.MaintenanceWindowValidationException; import com.edgecloud.alert.repository.*;
class MaintenanceWindowServiceTest {private MaintenanceWindowRepository windows=mock(MaintenanceWindowRepository.class);private MaintenanceWindowService service=new MaintenanceWindowService(windows,mock(AlertSuppressionHistoryRepository.class),mock(MaintenanceWindowAuditRepository.class));private Instant start=Instant.now().plusSeconds(60),end=start.plusSeconds(60);
 @Test void validatesRangeAndScopeTargets(){assertThatThrownBy(()->service.create(UUID.randomUUID(),request(MaintenanceScopeType.PROJECT,UUID.randomUUID(),null,start,end),UUID.randomUUID())).isInstanceOf(MaintenanceWindowValidationException.class);assertThatThrownBy(()->service.create(UUID.randomUUID(),request(MaintenanceScopeType.DEVICE,null,null,start,end),UUID.randomUUID())).isInstanceOf(MaintenanceWindowValidationException.class);assertThatThrownBy(()->service.create(UUID.randomUUID(),request(MaintenanceScopeType.PROJECT,null,null,end,start),UUID.randomUUID())).isInstanceOf(MaintenanceWindowValidationException.class);}
 private MaintenanceWindowRequest request(MaintenanceScopeType scope,UUID service,String device,Instant from,Instant to){return new MaintenanceWindowRequest(scope,service,device,"Window","Reason",from,to,true);}
}
